CREATE OR REFRESH STREAMING TABLE retail.gold.ventas_recientes
AS SELECT tienda_id, producto_id, unidades, monto, fecha_venta
FROM retail.silver.ventas;

CREATE OR REFRESH STREAMING TABLE banca.silver.pagos (
  CONSTRAINT pago_id_presente EXPECT (pago_id IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT monto_positivo   EXPECT (monto > 0),
  CONSTRAINT moneda_valida    EXPECT (moneda IN ('PEN', 'USD')) ON VIOLATION FAIL UPDATE
)
AS SELECT * FROM STREAM(banca.bronze.pagos);

