CREATE FUNCTION salud.seguridad.filtro_sede(sede STRING)
RETURNS BOOLEAN
RETURN is_account_group_member('direccion_medica')
    OR (is_account_group_member('sede_arequipa') AND sede = 'AREQUIPA');

ALTER TABLE salud.silver.atenciones
SET ROW FILTER salud.seguridad.filtro_sede ON (sede);
